questionvariables.text:
/* Design: estimate an area by counting squares, using F + P/2 (F whole squares, P part squares). Entries [R, a, b, phase, cx, cy, F, P]: a blob r(t) = R(1 + a cos 2(t - phase) + b cos 3t) on a 12 by 9 grid. F and P are exact counts, and the general-feedback board's JavaScript reproduces them on every entry. Source: original; method as in SMP GCSE Foundation 2, Chapter 18, Section A (whole and half squares on squared paper). */
L: [[2.8,0.1,0.1,1.6,6.49,4.46,14,22],[2.8,0.2,0.12,1.6,5.31,4.46,13,20],[2.6,0.2,0.05,2.4,5.81,4.73,12,20],[3.0,0.1,0.12,2.0,6.76,4.33,16,22],[2.8,0.15,0.05,2.0,5.73,4.54,15,22],[3.2,0.1,0.05,0.8,5.33,4.48,20,24],[2.6,0.15,0.08,0.4,6.26,4.21,13,22],[3.4,0.15,0.08,0.4,5.71,4.65,24,26],[3.2,0.15,0.08,1.6,6.78,4.51,20,26],[2.8,0.25,0.08,0.8,6.15,4.63,15,24]];
ix: 1+rand(10);
Rr: L[ix][1]; aa: L[ix][2]; bb: L[ix][3]; ph: L[ix][4]; cx: L[ix][5]; cy: L[ix][6];
nF: L[ix][7]; nP: L[ix][8];
cc: rand(3);
s: rand([2,5,10]);
sq: s^2;
est: nF + nP/2;
area: sq*est;

feedbackvariables.text:
cok: is(abs(ans1-nF) <= 1 and abs(ans2-nP) <= 2);
dbl: is(ans1 >= nF+2 and abs(ans1+ans2-(nF+nP)) <= 2);
mis: is(abs(ans1-nF) <= 1 and ans2 <= nP-3);
